import { logger, Tree } from '@nx/devkit';

import { flutterWebFiles } from '../../lib/utils/flutter-web';
import { readProjects } from '../../lib/utils/project-json-files';

interface Target {
  executor?: string;
  options?: { target?: string };
}

const FLUTTER_BUILD = '@mouryaamit/nx-polystack:flutter-build';

/**
 * v1.0.0: Flutter apps generated by earlier versions had no web/ folder, so `flutter build web`
 * (the build-web and serve targets) stopped with "This project is not configured for the web".
 * Adds web/index.html and web/manifest.json to apps built with the plugin's flutter-build executor
 * for the web target. Apps that already have web/index.html are left alone.
 */
export default async function flutterWebPlatform(tree: Tree): Promise<void> {
  const added: string[] = [];
  for (const { name, root, json } of readProjects(tree)) {
    const targets = (json.targets ?? {}) as Record<string, Target>;
    const buildsWeb = Object.values(targets).some(
      (t) => t.executor === FLUTTER_BUILD && (t.options?.target ?? 'web') === 'web',
    );
    if (!buildsWeb || !tree.exists(`${root}/pubspec.yaml`)) continue;
    if (tree.exists(`${root}/web/index.html`)) continue;
    for (const [file, content] of Object.entries(flutterWebFiles(name))) {
      const target = `${root}/${file}`;
      if (!tree.exists(target)) tree.write(target, content);
    }
    added.push(name);
  }
  if (added.length > 0) {
    logger.info(
      `flutter-web-platform: web/index.html and web/manifest.json added to ${added.join(', ')}. ` +
        'Needs Flutter 3.22 or later (flutter_bootstrap.js); add icons under web/ if you want them.',
    );
  }
}
